let voices=[],activeVoice=null,speechToken=0,pendingSpeech='',audioContext;
const reducedMotion=()=>saved.gentle||window.matchMedia('(prefers-reduced-motion: reduce)').matches;
// The Web Speech API exposes names and languages, not a gender field.
function voiceScore(v){if(!/^en(?:-|_)/i.test(v.lang))return -1000;let score=0;const name=v.name.toLowerCase();if(/female|zira|samantha|victoria|karen|moira|tessa|susan|hazel|aria|jenny|sonia|ava/.test(name))score+=100;if(/google.*female/.test(name))score+=100;if(/natural|neural|premium|enhanced/.test(name))score+=60;if(/google us english/.test(name))score+=85;if(/male|david|mark|george|daniel|james/.test(name)&&!/female/.test(name))score-=160;if(/en[-_]us/i.test(v.lang))score+=10;return score;}
function loadVoices(){
 if(!('speechSynthesis' in window)){ $('voice-info').textContent='Speech is not available in this browser. The game still works without audio.';$('voice-preview').disabled=true;return; }
 voices=speechSynthesis.getVoices().filter(v=>/^en(?:-|_)/i.test(v.lang));
 activeVoice=voices.find(v=>v.voiceURI===saved.voiceURI)||[...voices].sort((a,b)=>voiceScore(b)-voiceScore(a))[0]||null;
 const select=$('voice-choice');select.replaceChildren(new Option('Automatic · prefer a female English voice',''));
 [...voices].sort((a,b)=>voiceScore(b)-voiceScore(a)).forEach(v=>select.add(new Option(`${v.name} (${v.lang})`,v.voiceURI)));
 select.value=voices.some(v=>v.voiceURI===saved.voiceURI)?saved.voiceURI:'';
 $('voice-info').textContent=activeVoice?`Using ${activeVoice.name}. Try the voice on your smartboard; available voices come from Chrome and the connected device.`:'Waiting for Chrome’s voices. Tap the speaker to enable audio. If no English voice appears, enable English text-to-speech on the connected device.';
 if(pendingSpeech&&activeVoice){const text=pendingSpeech;pendingSpeech='';say(text);}
}
function say(text){
 if(!saved.voice||!('speechSynthesis' in window))return;
 if(!activeVoice){loadVoices();if(!activeVoice){pendingSpeech=text;return;}}
 try{const token=++speechToken;speechSynthesis.cancel();$('helper').classList.remove('speaking');const utterance=new SpeechSynthesisUtterance(text);utterance.voice=activeVoice;utterance.lang=activeVoice.lang;utterance.rate=.93;utterance.pitch=1;
 utterance.onstart=()=>{if(token===speechToken)$('helper').classList.add('speaking');};
 const finish=()=>{if(token===speechToken)$('helper').classList.remove('speaking');};utterance.onend=finish;utterance.onerror=finish;speechSynthesis.speak(utterance);
 }catch{$('helper').classList.remove('speaking');}
}
function animateOnce(element,name){element.classList.remove(name);if(reducedMotion())return;void element.offsetWidth;element.classList.add(name);const finish=e=>{if(e.target!==element)return;element.classList.remove(name);element.removeEventListener('animationend',finish);};element.addEventListener('animationend',finish);}
function particle(text,x,y,dx,dy,kind='spark'){if(reducedMotion())return;const p=document.createElement('span');p.className=`particle ${kind}`;p.textContent=text;p.style.left=x+'px';p.style.top=y+'px';p.style.setProperty('--dx',dx+'px');p.style.setProperty('--dy',dy+'px');p.style.setProperty('--turn',(Math.random()*120-60)+'deg');$('effects-layer').append(p);p.addEventListener('animationend',()=>p.remove(),{once:true});setTimeout(()=>p.remove(),2200);}
function rewardAnimation(button){animateOnce($('customer'),'happy');animateOnce($('helper'),'happy');animateOnce(button,'reward-pop');animateOnce(document.querySelector('.wallet'),'coin-pop');const box=button.getBoundingClientRect(),wallet=document.querySelector('.wallet').getBoundingClientRect();const x=box.x+box.width/2,y=box.y+box.height/2;particle('★',x,y,wallet.x+wallet.width/2-x,wallet.y+wallet.height/2-y,'flying-coin');for(let i=0;i<12;i++){const a=i*Math.PI/6;particle(i%2?'✦':'★',x,y,Math.cos(a)*90,Math.sin(a)*75-30);}chime();}
function confetti(){if(reducedMotion())return;for(let i=0;i<40;i++){particle(['★','●','✦','■'][i%4],innerWidth*(.15+Math.random()*.7),innerHeight*.18,(Math.random()-.5)*400,innerHeight*.7,'confetti');}chime(true);}
function chime(big=false){if(!saved.effects)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});const now=audioContext.currentTime;[523.25,659.25,...(big?[783.99,1046.5]:[])].forEach((freq,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,now+i*.09);gain.gain.linearRampToValueAtTime(.035,now+i*.09+.01);gain.gain.exponentialRampToValueAtTime(.001,now+i*.09+.24);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.09);osc.stop(now+i*.09+.25);});}catch{} }
function shuffle(arr){for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}return arr;}
function updateChrome(){
 $('coins').textContent=saved.coins;document.body.classList.remove('sunshine','berry');if(saved.theme!=='coral')document.body.classList.add(saved.theme);document.body.classList.toggle('gentle',saved.gentle);
 $('sound').textContent=saved.voice?'♫ Voice on':'♫ Voice off';$('sound').setAttribute('aria-label',saved.voice?'Turn voice off':'Turn voice on');
 $('stages').innerHTML=labels.map((s,i)=>`<button data-stage="${i}" ${i>saved.unlocked&&!practice?'disabled':''} class="${i===stage?'active':''}" ${i===stage?'aria-current="step"':''}><span class="step">${i>saved.unlocked&&!practice?'▧':i+1}</span><span>${s}<small>${descriptions[i]}</small></span></button>`).join('');
 $('stages').querySelectorAll('button').forEach(b=>b.onclick=()=>{stage=Number(b.dataset.stage);round=saved.counts[stage]<8?saved.counts[stage]:0;newRound();});
 $('plant').innerHTML=saved.owned.includes('plant')?svg('<path d="M60 106V38" stroke="#6c9a64" stroke-width="5"/><ellipse cx="41" cy="63" rx="15" ry="29" transform="rotate(-40 41 63)" fill="#79ab72"/><ellipse cx="78" cy="53" rx="15" ry="29" transform="rotate(35 78 53)" fill="#95bb7d"/><path d="M31 95H91L80 138H43Z" fill="#dca37d"/>'):'';
}
// Checkout state machine. This source is combined with the shared art/voice helpers in game.js.
let phase='welcome',phaseTime=0,customerVisit=0,itemIndex=0,basket=[],packed=[],deck=[],deckSignature='',lastObject='',focus='starter',started=false,retryMessage='';
const durations={arrival:1000,loading:1000,moving:1300,packing:2700,retry:4000};
const arrivalMessage='Please put your items on the belt.';
const retryMessages=['You can do it! Take a breath and try again.','Keep trying! Every try helps you learn.','You have got this! Let us look carefully.','Mistakes help us learn. You can try again!'];
const baseObjects=Object.entries(window.SHOP_OBJECTS).flatMap(([letter,items])=>items.map(([name,art])=>({letter,name,art,id:letter+':'+name})));
const allObjects=window.SHOP_WORD_LIBRARY.map(x=>({...x,id:x.letter+':'+x.name}));
function itemArt(item){return products[item.art.toUpperCase()]||window.shopArt(item.art);}
function currentItem(){return basket[itemIndex];}
function introduction(item=currentItem()){if(!item)return 'Welcome to the supermarket!';const plural=['grapes','noodles'].includes(item.name);const article=(/^[aeiou]/.test(item.name)&&!['unicorn','uniform','ukulele','unicycle'].includes(item.name))||item.name.startsWith('x-ray')?'an':'a';return `${plural?'These are':'This is '+article} ${item.name}. ${item.letter} is for ${item.name}.`;}
function promptText(){if(phase==='retry')return retryMessage;if(phase==='arrival'||phase==='loading')return arrivalMessage;return stage===2&&phase==='ready'?'Which word names this item?':introduction();}
function allowedObjects(){if(teacherLesson)return allObjects.filter(x=>stage===2?teacherLesson.words.includes(x.name):teacherLesson.letters.includes(x.letter));return stage===2?baseObjects.filter(x=>SIMPLE_SHOP_WORDS.includes(x.name)):baseObjects.filter(x=>focus==='all'||focus==='starter'&&letters.includes(x.letter)||x.letter===focus);}
function drawObject(){const pool=allowedObjects(),signature=stage+':'+focus;if(signature!==deckSignature){deck=[];deckSignature=signature;}if(!deck.length){deck=shuffle([...pool]);if(deck.length>1&&deck[deck.length-1].id===lastObject)[deck[0],deck[deck.length-1]]=[deck[deck.length-1],deck[0]];}const result=deck.pop();lastObject=result.id;return result;}
function chrome(){updateChrome();$('round-label').textContent=started?`CUSTOMER ${customerVisit} · ${basket.length} ITEMS`:'CHECKOUT 01 · READY TO OPEN';$('customer-name').textContent=started?`Shopping with ${names[(customerVisit-1)%names.length]}`:'Your friends are ready to shop.';const count=saved.counts[stage];$('progress-label').textContent=`${labels[stage]} · ${count} / 8 scans to unlock`;if(count===8)$('progress-label').textContent=`${labels[stage]} · stage complete ★`;$('dots').innerHTML=Array.from({length:8},(_,i)=>`<span class="${i<count?'done':''}"></span>`).join('');$('basket-progress').innerHTML=basket.map((_,i)=>`<span class="basket-dot ${i<itemIndex||phase==='receipt'?'packed':i===itemIndex?'current':''}" aria-label="Item ${i+1} ${i<itemIndex?'packed':'waiting'}"></span>`).join('');}
function setPhase(nextPhase){phase=nextPhase;phaseTime=0;if(phase!=='arrival')$('customer').classList.remove('arriving');document.querySelector('.shop').classList.toggle('ready',phase==='ready');document.querySelector('.shop').classList.toggle('retrying',phase==='retry');document.querySelector('.shop').classList.toggle('belt-running',phase==='moving'||phase==='loading');if(phase!=='loading')customerMotion.reset();$('hint').disabled=phase==='retry';if(phase!=='retry')retryMessage='';if(phase!=='packing'){$('scanner').classList.remove('scanning');cashierMotion.reset();}}
function actors(){for(const [id,bear] of [['customer',customerVisit%2===0],['helper',true]]){$(id).innerHTML=animal(bear);const art=$(id).querySelector('svg');art.querySelectorAll('ellipse[fill="#344846"]').forEach(eye=>eye.classList.add('eye'));art.insertAdjacentHTML('beforeend','<g class="waving-arm"><path d="M91 126Q110 123 110 104" fill="none" stroke="'+(bear?'#c28b5c':'#fff8e9')+'" stroke-width="13" stroke-linecap="round"/></g>');} $('customer').classList.remove('leaving');}
function newRound(){
session++;started=true;correct=false;hints=0;customerVisit++;itemIndex=0;packed=[];basket=[];const size=Math.min(allowedObjects().length,2+Math.floor(Math.random()*4));while(basket.length<size){const item=drawObject();if(!basket.some(x=>x.id===item.id))basket.push(item);}actors();$('customer-basket').innerHTML=`<span>${basket.length}</span>`;$('bag-items').replaceChildren();$('choices').replaceChildren();$('target').textContent='?';$('item-name').textContent='';$('task-label').textContent=stage===2?'WORD CHECKOUT':'LETTER CHECKOUT';$('instruction').textContent='Here comes a customer!';$('feedback').textContent='Let’s see what’s in the basket.';$('cashier-speech').textContent=arrivalMessage;$('next').hidden=true;$('hint').hidden=true;$('belt-items').innerHTML=basket.map((item,i)=>`<div class="belt-object" data-index="${i}" style="left:14%;visibility:hidden">${itemArt(item)}</div>`).join('');setPhase('arrival');animateOnce($('customer'),'arriving');chrome();renderTransport();say(arrivalMessage);
}
function beginLoading(){durations.loading=basket.length*900;setPhase('loading');$('instruction').textContent='Put the items on the conveyor.';renderTransport();}
function beginMoving(){setPhase('moving');correct=false;hints=0;$('choices').replaceChildren();$('hint').hidden=true;$('next').hidden=true;$('instruction').textContent='Here comes the next item…';$('feedback').textContent='Watch it travel to the scanner.';$('cashier-speech').textContent='Let’s bring it to the till.';[...$('belt-items').children].forEach(el=>el.classList.remove('loading'));}
function itemReady(){
setPhase('ready');const item=currentItem();target=stage===2?item.name.toUpperCase():item.letter;
const pool=stage===2?(teacherLesson?[...new Set([...teacherLesson.words,...SIMPLE_SHOP_WORDS])]:SIMPLE_SHOP_WORDS).map(x=>x.toUpperCase()):'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');choices=shuffle([target,...shuffle(pool.filter(x=>x!==target)).slice(0,2)]);
$('target').textContent=stage===2?'?':item.letter;$('item-name').textContent=stage===2?'Read the word':item.name;$('instruction').textContent=stage===2?'Which word names this item?':'Tap the letter to scan this item.';$('task-label').textContent=stage===2?'READ & SCAN':'LEARN & SCAN';$('feedback').textContent=stage===1?`Find the little letter for ${item.letter}.`:stage===2?'Read a word on the till.':'Which letter starts this item?';$('cashier-speech').textContent=stage===2?'Can you read the word for this item?':introduction(item);
$('choices').innerHTML=choices.map((value,i)=>`<button class="choice ${stage===2?'word':''}" data-answer="${value}" aria-label="${stage===1?value.toLowerCase():value}">${stage===1?value.toLowerCase():value}<span class="key">${i+1}</span></button>`).join('');$('choices').querySelectorAll('button').forEach(b=>b.onclick=()=>answer(b.dataset.answer));$('hint').hidden=false;renderTransport();say(promptText());
}
function answer(value){if(phase!=='ready'||correct)return;const button=[...$('choices').children].find(b=>b.dataset.answer===value);if(!button)return;if(value!==target){startRetry(button);return;}correct=true;const praise=nextEncouragement();saved.coins++;saved.counts[stage]=Math.min(8,saved.counts[stage]+1);if(saved.counts[stage]===8)saved.unlocked=Math.max(saved.unlocked,Math.min(2,stage+1));persist();button.classList.add('correct');[...$('choices').children].forEach(b=>b.disabled=true);$('hint').hidden=true;$('feedback').textContent='Pick it up, scan it, and pop it in the bag.';document.getElementById('cashier-speech').textContent=stage===2?praise+' '+introduction():praise;if(stage===2){$('target').textContent=target;$('item-name').textContent=currentItem().name;}setPhase('packing');cashierMotion.start(document.getElementById("belt-items").children[itemIndex]);scanSoundPlayed=false;rewardAnimation(button);chrome();say(stage===2?praise+" "+introduction():praise);}
function startRetry(button){setPhase('retry');retryMessage=retryMessages[Math.floor(Math.random()*retryMessages.length)];animateOnce(button,'wrong');[...$('choices').children].forEach(b=>b.disabled=true);$('cashier-speech').textContent=retryMessage;renderRetry();say(retryMessage);}
function renderRetry(){const seconds=Math.max(1,Math.ceil((durations.retry-phaseTime)/1000)),message=`Try again in ${seconds} ${seconds===1?'second':'seconds'}…`;if($('feedback').textContent!==message)$('feedback').textContent=message;}
function finishRetry(){setPhase('ready');[...$('choices').children].forEach(b=>b.disabled=false);$('feedback').textContent=stage===2?'Read a word on the till.':stage===1?`Find the little letter for ${currentItem().letter}.`:'Which letter starts this item?';$('cashier-speech').textContent='You can do it! Try again.';say('You can do it! Try again.');}
function finishPacking(){cashierMotion.reset();packed.push(currentItem());$('bag-items').innerHTML=packed.map(itemArt).join('');$('belt-items').children[itemIndex].style.visibility='hidden';itemIndex++;chrome();if(itemIndex<basket.length)beginMoving();else finishCustomer();}
